    45	function parseDate(input?: string): DateTime | undefined {
    46	  if (input === undefined || input.length == 0) {
    47	    return undefined;
    48	  }
    49	
    50	  const result = DateTime.fromISO(input);
    51	
    52	  if (!result.isValid) {
