    16	  readonly arguments: string;
    17	  readonly auth: Auth;
    18	  readonly spreadsheet: Spreadsheet;
    19	  readonly sheetName: string;
    20	  readonly interval: Interval;
    21	  readonly notifier: Notifier;
    22	
    23	  constructor(options: ReportOptions) {
    24	    this.arguments = options.arguments;
    25	    this.auth = options.auth;
    26	    this.spreadsheet = options.spreadsheet;
    27	    this.sheetName = options.sheetName;
    28	    this.interval = options.interval;
    29	    this.notifier = options.notifier;
    30	  }
    31	
    32	  abstract run(): Promise<void>;
    33	
    34	  protected async getOrCreateTable<T extends Row>(headerValues: HeaderValues<T>) {
    35	    const worksheet = await this.spreadsheet.getOrCreateWorksheet(this.sheetName, headerValues);
    36	    return worksheet.getTable();
    37	  }
    38	
    39	  /**
    40	   * Extends a Parse query to filter the results to be between this report's interval.
    41	   */
    42	  protected updatedBetween<T extends Parse.Object<Parse.BaseAttributes>>(query: Parse.Query<T>) {
    43	    if (this.interval.start) {
    44	      query.greaterThanOrEqualTo("updatedAt", this.interval.start.toJSDate());
    45	    }
    46	    if (this.interval.end) {
    47	      query.lessThan("updatedAt", this.interval.end.toJSDate()!);
    48	    }
    49	    return query;
    50	  }
    51	
    52	  /**
    53	   * Reconfigure a JS Date object to a date-string configured for the spreadsheet's timezone and locale.
    54	   */
    55	  protected reconfigureDate(date: Date) {
    56	    // Clubspot dates are UTC, we want to convert these to the spreadsheet
    57	    const utcDate = DateTime.fromJSDate(date, {
    58	      zone: FixedOffsetZone.utcInstance,
    59	    });
    60	    const locale = this.spreadsheet.locale.replace("_", "-");
    61	    return utcDate.setLocale(locale).setZone(this.spreadsheet.timeZone);
    62	  }
    63	
    64	  /**
    65	   * Formats a JS Date object with the spreadsheet's locale and timezone.
    66	   * @param date For
    67	   */
    68	  protected formatDate(date?: Date, formatOpts?: Intl.DateTimeFormatOptions) {
    69	    if (date === undefined) {
    70	      return "";
    71	    }
    72	
    73	    return this.reconfigureDate(date).toLocaleString(formatOpts ?? DateTime.DATE_SHORT);
    74	  }
    75	}
