     3	import { Command, Option } from "@commander-js/extra-typings";
     4	import winston from "winston";
     5	import { Clubspot, ClubspotUsernameOption, ClubspotPasswordOption } from "@cyc-seattle/clubspot-sdk";
     6	import { LoggingOption, VerboseOption } from "@cyc-seattle/commodore";
     7	import { Auth, google } from "googleapis";
     8	import { ReportRunner } from "./runner.js";
     9	import { RosterGenerator } from "./roster.js";
    10	
    11	// Outh Scopes: https://developers.google.com/identity/protocols/oauth2/scopes
    12	const auth: Auth.GoogleAuth = new google.auth.GoogleAuth({
    13	  scopes: [
    14	    "https://www.googleapis.com/auth/spreadsheets",
    15	    // `drive` (not `drive.file`) is required to create rosters inside a shared-drive
    16	    // folder the app did not itself create.
    17	    "https://www.googleapis.com/auth/drive",
    18	    "https://www.googleapis.com/auth/cloud-platform",
    19	  ],
    20	});
    21	
    22	const clubspot = new Clubspot();
    23	const reportRunner = new ReportRunner(auth);
    24	
    25	// TODO: dry run option
    26	const program = new Command("admin-scripts")
    27	  .addOption(new ClubspotUsernameOption())
    28	  .addOption(new ClubspotPasswordOption())
    29	  .addOption(new LoggingOption())
    30	  .addOption(new VerboseOption("info"))
    31	  .hook("preAction", async (command, action) => {
    32	    const opts = command.opts();
    33	
    34	    winston.configure({
    35	      level: opts.verbose ?? "info",
    36	      format: opts.logging,
    37	      transports: new winston.transports.Stream({ stream: process.stderr }),
    38	    });
    39	
    40	    await clubspot.initialize(opts.username, opts.password);
    41	
    42	    winston.debug("Executing action", {
    43	      action: action.name(),
    44	      options: action.opts(),
    45	    });
    46	  });
    47	
    48	const configSheetOption = new Option("--config-spreadsheet <id>", "The ID of the configuration spreadsheet")
    49	  .env("CONFIG_SPREADSHEET_ID")
    50	  .makeOptionMandatory();
    51	
    52	program
