    54	  .description("Runs all reports defined in the specified config spreadsheet.")
    55	  .addOption(configSheetOption)
    56	  .action(async (options) => {
    57	    await reportRunner.runAll(options.configSpreadsheet);
    58	  });
    59	
    60	const rosterFolderOption = new Option("--folder <id>", "Drive folder id to create the roster in")
    61	  .env("ROSTER_FOLDER_ID")
    62	  .default("1Iu6x4t0bFE_Yt0MMV21fvEOQpt_xocEU");
    63	
    64	program
    65	  .command("roster")
    66	  .description("Generates a fresh camp roster (Public + Medical tabs) for one camp session.")
    67	  .requiredOption("--camp <id>", "The Clubspot camp id")
    68	  .requiredOption("--session <name-or-id>", "The session (week) name or id")
