   113	     * longer have the removed session. Since we don't have the removed session ids any more, we can't
   114	     * remove the old rows so we will have cancelled participants still in our list.
   115	     *
   116	     * This hacky solution is to find all existing rows with the same registration and participant ids
   117	     * and to mark them as "cancelled".  This designation will get overwritten if a sessionJoinObject
   118	     * DOES exist for those rows.
   119	     */
   120	    winston.info("Temporarily cancelling all existing records");
   121	    for (const registration of registrations) {
   122	      for (const participant of registration.get("participantsArray") ?? []) {
