   142	          const campClass = joinObject.get("campClassObject");
   143	          const className = campClass.get("name");
   144	          const sessionName = campSession.get("name") ?? "Cancelled";
   145	
   146	          const result = table.addOrUpdate(["Registration Id", "Participant Id", "Class", "Session"], {
   147	            "Registration Id": registration.id,
   148	            "Participant Id": participant.id,
   149	            "Session Join Id": joinObject.id,
   150	            "First Name": firstName,
   151	            "Last Name": lastName,
   152	            Camp: campName,
   153	            Class: className,
   154	            Session: sessionName,
   155	            "Session Start": this.formatDate(campSession.get("startDate")),
   156	            Status: this.calculateStatus(registration, joinObject),
   157	            "Registration Date": this.formatDate(registration.get("confirmed_at")),
   158	            "Date of Birth": this.formatDate(participant.get("DOB")),
   159	            Gender: participant.get("gender"),
   160	
   161	            Email: participant.get("email"),
   162	            Mobile: participant.get("mobile"),
   163	            "Postal Code": participant.get("zip"),
   164	
   165	            "Emergency Contact": participant.get("emergencyContact"),
   166	            "Emergency Contact Mobile": participant.get("emergencyMobile"),
   167	
   168	            "First Guardian": participant.get("parentGuardianName"),
   169	            "First Guardian Email": participant.get("parentGuardianEmail"),
   170	            "First Guardian Mobile": participant.get("parentGuardianMobile"),
   171	
   172	            "Second Guardian": participant.get("parentGuardianName_secondary"),
   173	            "Second Guardian Email": participant.get("parentGuardianEmail_secondary"),
   174	            "Second Guardian Mobile": participant.get("parentGuardianMobile_secondary"),
   175	
   176	            "Medical Details": participant.get("medical"),
   177	            Allergies: participant.get("medical_allergies"),
   178	            Medication: participant.get("medical_meds"),
   179	            "Last Tetanus Shot": participant.get("medical_tetanus"),
   180	          });
   181	
   182	          if (!result.existing) {
   183	            await this.notifier.sendMessage(
   184	              `*${firstName} ${lastName}* registered for *${campName}*: ${className}, ${sessionName}!`,
   185	            );
   186	          }
   187	        }
   188	      }
   189	    }
   190	
   191	    await table.save();
   192	  }
   193	}
