     4	import { HeaderValues } from "@cyc-seattle/gsuite";
     5	import { DateTime } from "luxon";
     6	
     7	type RegistrationsRow = {
     8	  "Registration Id": string;
     9	  "Registration Date": string;
    10	  Participant: string;
    11	  Camp: string;
    12	  Classes: string;
    13	  Sessions: string;
    14	  Payment: number;
    15	  Paid: boolean;
    16	  Signatures: string | undefined;
    17	  Status: string | undefined;
    18	  Archived: boolean;
    19	  Deferred: number;
    20	  Pending: number;
    21	  Received: number;
    22	  Discount: number;
    23	  Refunded: number;
    24	};
    25	
    26	function formatCurrency(amount: number | undefined) {
    27	  if (amount === undefined) {
    28	    return 0;
    29	  } else {
    30	    return amount / 100;
    31	  }
    32	}
    33	
    34	export class RegistrationsReport extends Report {
    35	  static headers = [
    36	    "Registration Id",
    37	    "Registration Date",
    38	    "Participant",
    39	    "Camp",
    40	    "Classes",
    41	    "Sessions",
    42	    "Signatures",
    43	    "Status",
    44	    "Archived",
    45	    "Deferred",
    46	    "Pending",
    47	    "Received",
    48	    "Discount",
    49	    "Refunded",
    50	  ] satisfies HeaderValues<RegistrationsRow>;
    51	
    52	  get campId() {
    53	    return this.arguments;
    54	  }
    55	
    56	  public async run() {
    57	    const table = await this.getOrCreateTable<RegistrationsRow>(RegistrationsReport.headers);
    58	
    59	    const camp = await new LoggedQuery(Camp).get(this.campId);
    60	    winston.info("Reporting registrations for camp", camp);
    61	
    62	    const registrationsQuery = new LoggedQuery(Registration)
    63	      .equalTo("campObject", camp)
    64	      .include("classes")
    65	      .include("sessions")
    66	      .include("billing_registration")
    67	      .limit(1000);
    68	
    69	    const registrations = await this.updatedBetween(registrationsQuery).find();
    70	
    71	    for (const registration of registrations) {
    72	      const registrationId = registration.id;
    73	      const firstName = registration.get("firstName")?.trim();
    74	      const lastName = registration.get("lastName")?.trim();
    75	      const participant = `${firstName} ${lastName}`;
    76	      const sessions =
    77	        registration
    78	          .get("sessions")
    79	          ?.map((session) => session.get("name"))
    80	          .join(", ") ?? "";
    81	      const classes =
    82	        registration
    83	          .get("classes")
    84	          ?.map((session) => session.get("name"))
    85	          .join(", ") ?? "";
    86	
    87	      const billing = registration.get("billing_registration");
    88	
    89	      const result = await table.addOrUpdate(["Registration Id"], {
    90	        "Registration Id": registrationId,
    91	        Camp: camp.get("name"),
    92	        "Registration Date": this.formatDate(registration.get("confirmed_at"), DateTime.DATETIME_SHORT_WITH_SECONDS),
    93	        Participant: participant,
    94	        Sessions: sessions,
    95	        Classes: classes,
    96	        Signatures: registration.get("waiver_status"),
    97	        Status: registration.get("status"),
    98	        Archived: registration.get("archived") ?? false,
    99	        Deferred: formatCurrency(billing?.get("amount_deferred")),
   100	        Pending: formatCurrency(billing?.get("amountPending")),
   101	        Received: formatCurrency(billing?.get("amount_received")),
   102	        Discount: formatCurrency(billing?.get("discount")),
   103	        Refunded: formatCurrency(billing?.get("amountRefunded")),
   104	      });
   105	
   106	      if (result.existing) {
   107	        await this.notifier.sendMessage(`*${participant}'s* registration for *${camp.get("name")}* was updated.`);
   108	      } else {
   109	        await this.notifier.sendMessage(
   110	          `*${participant}* registered for *${camp.get("name")}*: ${sessions}, ${classes}!`,
   111	        );
   112	      }
   113	    }
   114	
   115	    await table.save();
   116	  }
   117	}

