     1	import { LoggedQuery } from "./parse.js";
     2	import { Camp, Club, Contract, Payout, QboSyncEvent, Registration, SesEmailSuppression, Transaction } from "./types.js";
     3	
     4	/**
     5	 * Returns a query that is similar to that used on the Camps->Entries page of the Clubspot dashboard.
     6	 *
     7	 * Includes only confirmed registrations, but does NOT filter out archived (cancelled).
     8	 */
     9	export function queryCampEntries(camp: Camp): LoggedQuery<Registration> {
    10	  return (
    11	    new LoggedQuery(Registration)
    12	      .equalTo("campObject", camp)
    13	      .exists("confirmed_at")
    14	      .include("classes")
    15	      .include("sessions")
    16	      // @ts-expect-error - The Parse Typescript SDK isn't quite good enough to validate nested includes.
    17	      .include("sessionJoinObjects.campSessionObject")
    18	      // @ts-expect-error - The Parse Typescript SDK isn't quite good enough to validate nested includes.
    19	      .include("sessionJoinObjects.campClassObject")
    20	      .include("participantsArray")
    21	  );
    22	}
    23	
    24	/**
    25	 * Returns a query similar to the Events->Signups page of the Clubspot dashboard: confirmed
    26	 * registrations across all event types (camps, regattas, and social events) for a club.
    27	 */
    28	export function queryRegistrations(club: Club): LoggedQuery<Registration> {
    29	  return new LoggedQuery(Registration)
    30	    .equalTo("clubObject", club)
    31	    .equalTo("archived", false)
    32	    .containedIn("status", ["confirmed", "applied", "invited"])
    33	    .include("campObject")
    34	    .include("eventObject")
    35	    .include("regattaObject")
    36	    .include("billing_registration")
    37	    .include("participantsArray")
    38	    .addDescending("confirmed_at");
    39	}
    40	
    41	/**
    42	 * Returns a query for e-signature contracts (waivers, membership agreements, etc.), similar to
    43	 * the E-signatures->Contracts page of the Clubspot dashboard.
    44	 */
    45	export function queryContracts(club: Club): LoggedQuery<Contract> {
    46	  return new LoggedQuery(Contract)
    47	    .equalTo("clubObject", club)
    48	    .notEqualTo("archived", true)
    49	    .include("waiverObject")
    50	    .include("campObject")
    51	    .include("regattaObject")
    52	    .include("registrationObject")
    53	    .addDescending("createdAt");
    54	}
    55	
    56	/**
    57	 * Returns a query for the email bounce/unsubscribe suppression list. Check this before syncing
    58	 * anyone into another mailing system (Google Groups, Listmonk, etc.) so suppressed addresses
    59	 * aren't re-added.
    60	 */
    61	export function querySuppressedEmails(club: Club): LoggedQuery<SesEmailSuppression> {
    62	  return new LoggedQuery(SesEmailSuppression)
    63	    .equalTo("clubObject", club)
    64	    .notEqualTo("archived", true)
    65	    .addDescending("createdAt");
    66	}
    67	
    68	/**
    69	 * Returns a query for the general-ledger journal entries ("Journal entries" in the Clubspot
    70	 * dashboard) for a club within a date range - the ground truth that gets synced to QuickBooks
    71	 * Online. See also queryQboSyncEvents to check whether that sync actually ran.
    72	 */
    73	export function queryTransactions(club: Club, start: Date, end: Date): LoggedQuery<Transaction> {
    74	  return new LoggedQuery(Transaction)
    75	    .equalTo("clubObject", club)
    76	    .notEqualTo("archived", true)
    77	    .greaterThanOrEqualTo("event_timestamp", start)
    78	    .lessThanOrEqualTo("event_timestamp", end)
    79	    .include("chartsArray")
    80	    .addDescending("event_timestamp");
    81	}
    82	
    83	/**
    84	 * Returns a query for the QuickBooks Online nightly sync run history, useful for verifying the
    85	 * accounting sync actually succeeded. See Reporting->Accounting sync.
    86	 */
    87	export function queryQboSyncEvents(club: Club): LoggedQuery<QboSyncEvent> {
    88	  return new LoggedQuery(QboSyncEvent)
    89	    .equalTo("clubObject", club)
    90	    .notEqualTo("archived", true)
    91	    .notEqualTo("hidden", true)
    92	    .addDescending("succeeded_at");
    93	}
    94	
    95	/**
    96	 * Returns a query for Stripe payouts to the club's bank account, for reconciling Clubspot revenue
    97	 * against bank deposits. See Reporting->Payouts.
    98	 */
    99	export function queryPayouts(club: Club): LoggedQuery<Payout> {
   100	  return new LoggedQuery(Payout).equalTo("clubObject", club).notEqualTo("archived", true).addDescending("arrivalDate");
   101	}
