  1	import * as docker from "@pulumi/docker-build";
  2	import * as pulumi from "@pulumi/pulumi";
  3	import * as gcp from "@pulumi/gcp";
  4	import { artifactRepositoryAccess, artifactRepositoryUrl } from "./artifact-repository";
  5	import { location, projectId } from "../config";
  6	import { reportRunner } from "./identities";
  7	import { Secret } from "./secret";
  8	import { enableService } from "../services";
  9	
 10	// APIs this job needs: Cloud Run to host it, Cloud Scheduler to trigger it, Secret Manager for its
 11	// credentials, and the Workspace APIs it reads/writes at runtime.
 12	const runApi = enableService("run.googleapis.com");
 13	const schedulerApi = enableService("cloudscheduler.googleapis.com");
 14	const secretmanagerApi = enableService("secretmanager.googleapis.com");
 15	const runtimeApis = ["admin.googleapis.com", "sheets.googleapis.com", "drive.googleapis.com"].map(enableService);
 16	
 17	const secrets = {
 18	  "clubspot-username": new Secret("clubspot-username", { dependsOn: secretmanagerApi }),
 19	  "clubspot-password": new Secret("clubspot-password", { dependsOn: secretmanagerApi }),
 20	};
 21	
 22	// Grant the service account access to read secrets.
 23	for (const secret of Object.values(secrets)) {
 24	  secret.grant(reportRunner.member);
 25	}
 26	
 27	const imageName = "report-runner:latest";
 28	const imageTag = pulumi.concat(artifactRepositoryUrl, "/", imageName);
 29	
 30	// Authenticate the image push using an OAuth2 access token from the credentials
 31	// pulumi is running as, rather than relying on a docker credential helper (which
 32	// is awkward when building through podman, whose auth config lives elsewhere).
 33	new docker.Image(
 34	  "report-runner-image",
 35	  {
 36	    tags: [imageTag],
 37	    context: {
 38	      location: "../../../..",
 39	    },
 40	    platforms: ["linux/amd64"],
 41	    push: true,
 42	    registries: [
 43	      {
