     1	// A small REST client for Directus's own API — deliberately free of any `@pulumi/*` import so it's
     2	// unit testable (see directus.ts, whose dynamic resource providers call into here; importing
     3	// directus.ts itself isn't practical since its module-level code constructs real GCP/Pulumi
     4	// resources on load).
     5	
     6	// This package's tsconfig (@tsconfig/node20, lib: es2023, no DOM) hits an @types/node quirk where
     7	// the ambient `fetch`/`Response` types resolve to an empty structural type rather than undici's
     8	// real one (its conditional type meant to defer to DOM lib's Response misfires with no DOM lib
     9	// present either). Rather than cast at every call site, wrap `fetch` once with the shape we
    10	// actually use.
    11	export interface HttpResponse {
    12	  readonly ok: boolean;
    13	  readonly status: number;
    14	  text(): Promise<string>;
    15	  json(): Promise<unknown>;
    16	}
    17	
    18	export async function httpFetch(input: string, init?: RequestInit): Promise<HttpResponse> {
    19	  return (await fetch(input, init)) as unknown as HttpResponse;
    20	}
    21	
    22	/** Default timeout for {@link waitForReachable}. Callers now `dependsOn` substrate-apply.ts, so this
    23	 * is a safety net for container start/migration time, not a VM-boot budget (was 180s) - kept above
    24	 * typical Directus startup so it doesn't reintroduce flaky applies. */
    25	export const DEFAULT_REACHABLE_TIMEOUT_MS = 90_000;
    26	
    27	export async function waitForReachable(baseUrl: string, timeoutMs = DEFAULT_REACHABLE_TIMEOUT_MS): Promise<void> {
    28	  const start = Date.now();
    29	  let lastError: unknown;
    30	  while (Date.now() - start < timeoutMs) {
    31	    try {
    32	      const res = await httpFetch(`${baseUrl}/server/ping`);
    33	      if (res.ok) return;
    34	    } catch (error) {
    35	      lastError = error;
    36	    }
    37	    await new Promise((resolve) => setTimeout(resolve, 5_000));
    38	  }
    39	  throw new Error(
    40	    `Directus at ${baseUrl} did not become reachable within ${timeoutMs}ms (VM boot/DNS/TLS may still be in ` +
    41	      `progress — re-run \`pulumi up\` once it's up). Last error: ${String(lastError)}`,
    42	  );
    43	}
    44	
    45	export async function login(baseUrl: string, email: string, password: string): Promise<string> {
    46	  const res = await httpFetch(`${baseUrl}/auth/login`, {
    47	    method: "POST",
    48	    headers: { "Content-Type": "application/json" },
    49	    body: JSON.stringify({ email, password }),
    50	  });
    51	  if (!res.ok) {
    52	    throw new Error(`Directus login as ${email} failed: ${res.status} ${await res.text()}`);
    53	  }
    54	  return ((await res.json()) as { data: { access_token: string } }).data.access_token;
    55	}
    56	
    57	export async function directusRequest<T>(
    58	  baseUrl: string,
    59	  token: string,
    60	  method: string,
    61	  path: string,
    62	  body?: unknown,
    63	): Promise<T> {
    64	  const res = await httpFetch(`${baseUrl}${path}`, {
    65	    method,
    66	    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    67	    body: body !== undefined ? JSON.stringify(body) : undefined,
    68	  });
    69	  if (!res.ok) {
    70	    throw new Error(`${method} ${path} -> ${res.status}: ${await res.text()}`);
    71	  }
    72	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
    73	}
    74	
    75	async function schemaDiff(
    76	  baseUrl: string,
    77	  token: string,
    78	  schema: unknown,
    79	): Promise<{ hash: string; diff: unknown } | null> {
    80	  // Found while verifying #109 against a real instance: when the submitted snapshot is already in
    81	  // sync, Directus returns a bare `204 No Content` (empty body), not `200 { data: null }`.
    82	  // `directusRequest`'s own 204 handling already turns that into `undefined` - treat it the same as
    83	  // `{ data: null }` rather than crashing on `res.data`. Pre-existing bug, unrelated to #109's
    84	  // cross-app-deletion issue, but on this exact function and newly reachable now that a scoped diff
    85	  // can genuinely come back empty (pre-#109, an unscoped diff on a shared instance essentially
    86	  // never did, since it always proposed deleting every other app's collections).
    87	  const res = await directusRequest<{ data: { hash: string; diff: unknown } | null } | undefined>(
    88	    baseUrl,
    89	    token,
    90	    "POST",
    91	    "/schema/diff",
    92	    schema,
    93	  );
    94	  return res?.data ?? null;
    95	}
    96	
    97	// The slice of a Directus schema snapshot (as returned by GET /schema/snapshot, and accepted by
    98	// POST /schema/diff) that applySchema's scoping logic below needs to touch. Collections, fields, and
    99	// relations are each keyed by their own `collection` field - for a relation that's the owning
   100	// ("many") side, which is always a collection this app owns whenever this app owns the relation.
   101	interface DirectusSnapshotEntry {
   102	  collection: string;
   103	}
   104	
   105	interface DirectusSnapshot {
   106	  version: number;
   107	  directus: string;
   108	  vendor: string;
   109	  collections: DirectusSnapshotEntry[];
   110	  fields: DirectusSnapshotEntry[];
   111	  relations: DirectusSnapshotEntry[];
   112	}
   113	
   114	async function getSnapshot(baseUrl: string, token: string): Promise<DirectusSnapshot> {
   115	  const res = await directusRequest<{ data: DirectusSnapshot }>(baseUrl, token, "GET", "/schema/snapshot");
   116	  return res.data;
   117	}
