  4	// the ambient `fetch`/`Response` types resolve to an empty structural type rather than undici's
  5	// real one. Rather than cast at every call site, wrap `fetch` once with the shape we actually use.
  6	export interface HttpResponse {
  7	  readonly ok: boolean;
  8	  readonly status: number;
  9	  text(): Promise<string>;
 10	  json(): Promise<unknown>;
 11	}
 12	
 13	export async function httpFetch(input: string, init?: RequestInit): Promise<HttpResponse> {
 14	  return (await fetch(input, init)) as unknown as HttpResponse;
 15	}
