 17	/** A single Directus REST filter, e.g. `{ email: { _eq: "a@b.com" } }`. */
 18	export type DirectusFilter = Record<string, Record<string, string | number | boolean>>;
 19	
 20	export interface ItemQuery {
 21	  filter?: DirectusFilter;
 22	  /** Row cap, or -1 for every row (the client pages through them transparently). */
 23	  limit?: number;
 24	  fields?: string[];
 25	  sort?: string[];
 26	}
 27	
 28	// Directus caps a single page well below what "every row" needs, so `limit: -1` is paged internally
 29	// at this size rather than trusting the server to hand back everything in one response.
 30	const PAGE_SIZE = 500;
 31	
 32	function filterToParams(filter: DirectusFilter): [string, string][] {
 33	  const params: [string, string][] = [];
 34	  for (const [field, operators] of Object.entries(filter)) {
 35	    for (const [operator, value] of Object.entries(operators)) {
 36	      params.push([`filter[${field}][${operator}]`, String(value)]);
 37	    }
 38	  }
 39	  return params;
 40	}
 41	
 42	function queryToParams(query: ItemQuery): URLSearchParams {
 43	  const params = new URLSearchParams();
 44	  if (query.filter) {
 45	    for (const [key, value] of filterToParams(query.filter)) {
 46	      params.set(key, value);
 47	    }
 48	  }
 49	  if (query.fields) {
 50	    params.set("fields", query.fields.join(","));
 51	  }
 52	  if (query.sort) {
 53	    params.set("sort", query.sort.join(","));
 54	  }
 55	  return params;
 56	}
